('200037','200','Fornecimento de serviços ambientais de conservação ou recuperação da vegetação nativa','Fornecimento de serviços ambientais de conservação ou recuperação da vegetação nativa, mesmo que fornecidos sob a forma de manejo sustentável de sistemas agrícolas, agroflorestais e agrossilvopastoris, em conformidade com as definições e requisitos da legislação específica, observado o art. 137 da Lei Complementar nº 214, de 2025.',60,60,'2026-01-01'::date,NULL,false,'{"tipoAliquota":"Padrão","indTribRegular":0,"indCredPresOper":0,"indMonoPadrao":0,"indMonoReten":0,"indMonoRet":0,"indMonoDif":0,"tpRBSN":1,"indNFe":0}'::jsonb,'IT2025.002-v1.60-2026-06-22','2026-06-22'::date,'https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp214.htm#art137'),
