('200039','200','Fornecimento dos bens e serviços relacionados com produções nacionais artísticas, culturais, de eventos, jornalísticas e audiovisuais (Anexo X)','Fornecimento dos bens e serviços listados no Anexo X da Lei Complementar nº 214, de 2025, com a especificação das respectivas classificações da NCM/SH e NBS, nos casos relacionados com produções nacionais artísticas, culturais, de eventos, jornalísticas e audiovisuais, observado o art. 139 da Lei Complementar nº 214, de 2025.',60,60,'2026-01-01'::date,NULL,true,'{"tipoAliquota":"Padrão","indTribRegular":0,"indCredPresOper":0,"indMonoPadrao":0,"indMonoReten":0,"indMonoRet":0,"indMonoDif":0,"tpRBSN":1,"indNFe":1}'::jsonb,'IT2025.002-v1.60-2026-06-22','2026-06-22'::date,'https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp214.htm#art139'),
('200040','200','Fornecimento de serviços de comunicação institucional à administração pública','Fornecimento dos seguintes serviços de comunicação institucional à administração pública direta, autarquias e fundações públicas: serviços direcionados ao planejamento, criação, programação e manutenção de páginas eletrônicas da administração pública, ao monitoramento e gestão de suas redes sociais e à otimização de páginas e canais digitais para mecanismos de buscas e produção de mensagens, infográficos, painéis interativos e conteúdo institucional, serviços de relações com a imprensa, que reúnem estratégias organizacionais para promover e reforçar a comunicação dos órgãos e das entidades contratantes com seus públicos de interesse, por meio da interação com profissionais da imprensa, e serviços de relações públicas, que compreendem o esforço de comunicação planejado, coeso e contínuo que tem por objetivo estabelecer adequada percepção da atuação e dos objetivos institucionais, a partir do estímulo à compreensão mútua e da manutenção de padrões de relacionamento e fluxos de informação entre os órgãos e as entidades contratantes e seus públicos de interesse, no País e no exterior, observado o art. 140 da Lei Complementar nº 214, de 2025.',60,60,'2026-01-01'::date,NULL,false,'{"tipoAliquota":"Padrão","indTribRegular":0,"indCredPresOper":0,"indMonoPadrao":0,"indMonoReten":0,"indMonoRet":0,"indMonoDif":0,"tpRBSN":1,"indNFe":0}'::jsonb,'IT2025.002-v1.60-2026-06-22','2026-06-22'::date,'https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp214.htm#art140'),
('200041','200','Fornecimento de serviço de educação desportiva (art. 141. I)','Operações relacionadas às seguintes atividades desportivas: fornecimento de serviço de educação desportiva, classificado no código 1.2205.12.00 da NBS, observado o art. 141 da Lei Complementar nº 214, de 2025.',60,60,'2026-01-01'::date,NULL,false,'{"tipoAliquota":"Padrão","indTribRegular":0,"indCredPresOper":0,"indMonoPadrao":0,"indMonoReten":0,"indMonoRet":0,"indMonoDif":0,"tpRBSN":1,"indNFe":0}'::jsonb,'IT2025.002-v1.60-2026-06-22','2026-06-22'::date,'https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp214.htm#art141'),
